const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={home:'总览',scope:'能力目录',plugins:'插件',config:'工程配置',clients:'Agent 客户端',connections:'MCP 与连接',knowledge:'知识与向量',manual:'使用手册',tasks:'任务与恢复'};
let project,catalog,manuals=[],page='home',search='',doc='',docTitle='',model,planId,activity=[];
const badge=(s,k='')=>`<span class="badge ${k}">${esc(s)}</span>`,button=(s,a,primary=false)=>`<button data-do="${a}" class="${primary?'primary':''}">${s}</button>`,link=(s,p)=>`<a href="#${p}">${s} →</a>`;
const title=(s,d,a='')=>`<div class="page-title"><div><h2>${s}</h2><p>${d}</p></div>${a}</div>`;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(v=>`<th>${v||'操作'}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const empty=(s,d,a='')=>`<div class="empty"><h3>${s}</h3><p>${d}</p>${a}</div>`;
const pluginNames={'agent-context-kit':'工程上下文','agent-framework-evolution':'框架反馈与演进','bos-plugin':'BOS 需求与日志','codegraph-query':'代码图查询','coding-iris-plugin':'IRIS 编码与部署','demand-delivery-plugin':'需求交付','extract-doc':'文档提取','i18n-iris-plugin':'IRIS 国际化','imedicalxc-doctor-card-reader':'医生站卡片读取','imedicalxc-doctor-codegraph':'医生站代码图','imedicalxc-doctor-data-extraction':'HIS 数据与接口映射','imedicalxc-doctor-extend-engineer':'医生站扩展开发','imedicalxc-doctor-perf-analysis-engineer':'医生站性能分析','imedicalxc-doctor-print-template-design':'HIS 打印模板','iris-codegraph':'IRIS 代码图','iris-cure-form-dev':'治疗表单开发','iris-external-reg':'外部挂号','iris-imedical-doctor-ai':'医生站 AI','iris-interface-dev':'IRIS 接口开发'};
const status=s=>({enabled:'已启用',disabled:'已停用',available:'已安装',pending:'待初始化'}[s]||'未识别');
const capabilities=[['配置与连接',[['工程信息与 IRIS','IRIS / Web / 已配置 SFTP 的跨文件预览与保存','config'],['BOS / 知识 Key','真实编辑、预览、用户保存与读回','connections'],['MCP 服务','读取注册字段；进程与认证测试待接通','connections']]],['能力与协作',[['插件','完整目录与实际 profile；安装启停待接通','plugins'],['Agent 客户端','提示词接续；自动派发未验证','clients'],['工程探索','需要 Agent 核对语义与业务事实','tasks']]],['维护与资料',[['部署 / 更新 / 恢复','需要接入 owner 执行与恢复回执','tasks'],['知识与向量','本地手册目录检索；向量构建待接通','knowledge'],['使用手册','随工具的 guides 原文，不是工程版本证明','manual']]]];
capabilities.push(['工程生命周期', [['首次接入 / 环境检查','安装助手已存在；工作台尚未派发部署任务','tasks'],['Overlay Root / 模块','演示可体验；实际模块注册与共享刷新尚未接入','config'],['升级 / 诊断 / 冲突恢复','沿 owner 检查；不会自动覆盖自定义配置','tasks'],['SQLite / 备份 / EXE','架构计划保留，当前未实现','tasks']]]);
function domain(d){return `<details class="domain"><summary><span><strong>${esc(d.name)}</strong><small>${esc(d.source)}</small></span><span>${badge(d.scope)} ${badge(d.status,d.status==='已真实读取'?'good':'warn')} <span class="count">${d.fields.length} 字段</span></span></summary>${table(['字段','状态','说明'],d.fields.map(f=>`<tr><td><code>${esc(f.key)}</code></td><td>${esc(f.status)}</td><td>${f.sensitive?'凭据值不回显':'只读识别'}</td></tr>`))}</details>`}
function content(){
if(page==='home')return title('工程总览','从实际状态开始，处理需要你关注的事项。',button('重新读取','refresh'))+`<section class="overview-band"><div><strong>${project.hasFramework?'已发现 .agents':'未发现 .agents'}</strong><p>只读识别完成 · 连接与宿主未验证</p></div><div><b>${project.plugins.filter(x=>x.status==='enabled').length}</b><span>明确启用的插件</span></div><div><b>${project.domains.length}</b><span>配置来源</span></div></section><div class="columns"><section><h3>接下来</h3><div class="action-list">${[['核对工程配置','来源、字段与空项','config'],['维护个人连接与 Key','BOS 和知识提供方支持预览后保存','connections'],['确认客户端接入','区分入口生成、宿主发现与实际调用','clients']].map(([n,d,p])=>`<a href="#${p}"><strong>${n}</strong><span>${d}</span><em>进入 →</em></a>`).join('')}</div></section><section><h3>工作台能力边界</h3><dl class="facts"><dt>真实读取</dt><dd>配置字段与插件 profile</dd><dt>真实保存</dt><dd>IRIS 工程连接、BOS / 知识个人配置</dd><dt>尚未执行</dt><dd>部署、MCP 认证测试、向量构建</dd><dt>需要 Agent</dt><dd>工程探索与自定义语义判断</dd></dl>${link('查看完整目录','scope')}</section></div>`;
if(page==='scope')return title('能力目录','按目标找到入口，明确当前支持范围。')+capabilities.map(([g,items])=>`<section class="catalog-group"><h3>${g}</h3><div>${items.map(([n,d,p])=>`<a href="#${p}" class="capability"><strong>${n}</strong><span>${d}</span><em>进入 →</em></a>`).join('')}</div></section>`).join('');
if(page==='plugins'){const list=catalog.plugins.filter(p=>(p.name+p.displayName+p.description+(pluginNames[p.name]||'')).toLowerCase().includes(search.toLowerCase()));return title('插件','目录来自源仓 manifest；启用状态来自当前工程 profile。')+`<div class="toolbar"><input id="search" aria-label="搜索插件" placeholder="搜索名称或用途" value="${esc(search)}"><span>${list.length} 项</span>${badge('基础能力固定保留')}</div>`+table(['能力','工程状态','版本',''],list.map(p=>`<tr><td><strong>${esc(pluginNames[p.name]||p.displayName||p.name)}</strong><small>${esc(p.name)}</small><details><summary>用途与依赖</summary><p>${esc(p.displayName||p.name)}</p><p>${esc(p.description)}</p><p>依赖：${esc(p.dependencies.join('、')||'无')}</p></details></td><td>${badge(status(project.plugins.find(x=>x.name===p.name)?.status),project.plugins.find(x=>x.name===p.name)?.status==='enabled'?'good':'')}</td><td>${esc(p.version)}</td><td>${catalog.basePlugins.includes(p.name)?badge('框架内置'):button('管理预览','plugin-'+p.name)}</td></tr>`));}
if(page==='config')return title('工程配置','已有配置先读取，不因进入工作台自动接管。')+`<div class="notice">IRIS 连接支持统一预览与保存：同步集中配置、VS Code、MCP、TOML 与受管 backend。Web 路径可编辑；SFTP 仅同步已识别的现有入口，不创建或启动服务。</div><section class="sheet"><div class="section-heading"><h3>工程来源</h3>${button('编辑工程连接','edit-project',true)}</div>${project.domains.filter(d=>d.scope==='当前工程').map(domain).join('')}</section><section class="sheet"><h3>领域配置</h3>${table(['文件','识别结果','操作'],project.profiles.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.exists?'存在，语义待核对':'未发现'}</td><td>${button('核对请求','handoff-'+p.name)}</td></tr>`))}</section><div class="related">${link('个人共享配置','connections')}<a href="/index.html#/clinic/config">配置交互演示（虚构数据） →</a></div>`;
if(page==='clients')return title('Agent 客户端','入口生成、宿主发现与实际调用分别验证。')+table(['客户端','已发现的工程入口','状态','操作'],(project.clients||[]).map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${c.entries.length?c.entries.map(esc).join('<br>'):'未发现项目级入口'}</td><td>${badge(c.entries.length?'入口已发现':'未发现入口',c.entries.length?'good':'')}<small>${esc(c.status)}</small></td><td>${button('准备接入请求','handoff-'+c.name)}</td></tr>`))+`<section class="sheet"><h3>接入检查顺序</h3><ol class="checklist"><li>确认工程入口与宿主</li><li>按框架脚本适配规则、Skills、Agents</li><li>重载宿主并检查发现</li><li>完成真实往返后确认调用可用</li></ol></section>`;
if(page==='connections')return title('MCP 与连接','个人连接复用；工程服务保持各自来源。')+`<section class="sheet"><div class="section-heading"><h3>个人连接档案</h3>${badge('共享影响，保存前确认','warn')}</div><div class="connection-list"><div><strong>BOS</strong><p>查询与日志分别配置，其他段保留。</p>${badge(project.domains[4].status)} ${button('编辑连接与凭据','edit-bos',true)}</div><div><strong>知识提供方</strong><p>公司网关与 OpenAI；模型变更需核对索引。</p>${badge(project.domains[5].status)} ${button('编辑提供方与 Key','edit-knowledge',true)}</div></div></section><section class="sheet"><h3>工程连接与 MCP</h3><p class="caption">IRIS / SFTP 引用工程连接字段。未启动进程，未测试认证。</p>${project.domains.filter(d=>/MCP|IRIS/.test(d.name)&&d.scope==='当前工程').map(domain).join('')}</section>`;
if(page==='knowledge')return title('知识与向量','先查本地资料；外发与构建需要独立授权。')+`<div class="toolbar"><input id="search" aria-label="搜索资料标题" placeholder="搜索手册标题" value="${esc(search)}">${link('模型与 Key','connections')}</div><div class="columns reading"><section><h3>本地资料目录</h3>${docList()}</section><aside class="sheet"><h3>向量索引</h3>${(project.indexes||[]).map(x=>`<p><strong>${esc(x.name)}</strong><br>${x.exists?`${Math.round(x.bytes/1024)} KB · 已发现本地文件`:'未发现索引文件'}</p>`).join('')}<p>已检查当前 .agents/.knowledge-cache；文件存在不代表索引可用，尚未验证维度与完整性。</p><dl class="facts"><dt>本次外发</dt><dd>无</dd><dt>构建 / 续建</dt><dd>沿既有 owner 执行</dd></dl>${button('准备构建核对请求','handoff-向量构建')}</aside></div>`;
if(page==='manual')return title('使用手册','读取源仓 guides；不自动执行文中命令。')+`<div class="manual-layout"><aside><input id="search" aria-label="筛选手册" placeholder="筛选标题" value="${esc(search)}">${docList()}</aside><article class="manual-article">${doc?`<h2>${esc(docTitle)}</h2><div class="related">${button('生成相关请求','handoff-手册接续')}<span>本地只读</span></div><div class="prose">${formatManual(doc)}</div>`:empty('选择一份使用手册','左侧按标题定位，正文在这里阅读。')}</article></div>`;
return title('任务与恢复','读取工程保存回执；临时接续记录仅在本次页面会话保留。')+((project.receipts||[]).length?table(['保存回执','状态','涉及文件','更新时间'],project.receipts.map(r=>`<tr><td><code>${esc(r.id)}</code></td><td>${esc(({applied:'已保存并读回',prepared:'写入未完成', 'reverted-after-failure':'失败后已恢复','reverted-after-interruption':'中断后已恢复','rolled-back':'已回滚'})[r.state]||r.state)}</td><td>${r.files}</td><td>${esc(r.updated)}</td></tr>`)):'')+(activity.length?`<ol class="timeline">${activity.map(x=>`<li><strong>${esc(x)}</strong><p>文件读回成功，远端认证未测试。</p></li>`).join('')}</ol>`:empty((project.receipts||[]).length?'本次打开后暂无新操作':'还没有工作台操作记录','先核对配置，或准备一项 Agent 请求。',link('管理连接','connections')+' '+button('准备工程检查请求','handoff-工程检查')))+`<section class="sheet"><h3>恢复边界</h3><p>保存前发现来源变化会停止；重新读取后编辑。数据库备份、跨机恢复尚未实现，不自动重放未知外部写。</p>${button('恢复诊断请求','handoff-恢复诊断')}</section>`;
}

function formatManual(text){const lines=text.split('\n');let html='',code=false;const inline=x=>esc(x).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{const file=url.split('#')[0].replace(/^\.\//,'');if(manuals.some(m=>m.file===file))return `<a href="#manual" data-doc="${file}">${label}</a>`;if(/^https:\/\//.test(url))return `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;return `${label} <small>（${url}）</small>`});for(let i=0;i<lines.length;i++){const line=lines[i];if(line.startsWith('```')){code=!code;html+=code?'<pre><code>':'</code></pre>';continue}if(code){html+=esc(line)+'\n';continue}if(line.trim().startsWith('|')){const rows=[];while(i<lines.length&&lines[i].trim().startsWith('|')){const cells=lines[i].trim().replace(/^\||\|$/g,'').split('|');if(!cells.every(c=>/^[:\s-]+$/.test(c)))rows.push(cells);i++}i--;html+=table(rows[0].map(inline),rows.slice(1).map(r=>'<tr>'+r.map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>'));continue}const h=line.match(/^(#{1,6}) (.*)/);if(h&&h[1]==='#'&&i<3)continue;if(h){html+='<h3>'+inline(h[2])+'</h3>';continue}if(line.trim())html+='<p>'+inline(line)+'</p>'}return html+(code?'</code></pre>':'')}

function docList(){return `<nav class="document-list">${manuals.filter(d=>d.title.includes(search)||d.file.includes(search)).map(d=>`<button data-doc="${esc(d.file)}" class="${docTitle===d.title?'selected':''}">${esc(d.title)}</button>`).join('')||empty('没有匹配资料','调整关键词。')}</nav>`}
function render(){document.title=project.name+' · .agents';document.getElementById('actual').innerHTML=`<div class="workbench"><aside class="sidebar"><a class="brand" href="#home"><span>·</span>agents</a><div class="workspace-label">工程工作台</div><nav>${[['工程',['home','config','plugins']],['协作与资源',['clients','connections','knowledge','manual']],['维护',['scope','tasks']]].map(([label,items])=>`<div class="nav-group">${label}</div>${items.map(k=>`<a href="#${k}" ${page===k?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${({home:'M3 10 12 3 21 10 M5 9v12h14V9 M10 21v-7h4v7',config:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',plugins:'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z',clients:'M3 4h18v13H3z M8 21h8 M12 17v4',connections:'M8 8H5a4 4 0 0 0 0 8h4 M16 8h3a4 4 0 0 1 0 8h-4 M8 12h8',knowledge:'M4 5h16v15H4z M8 9h8 M8 13h8 M8 17h4',manual:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 M12 5c4-3 8-2 10-1v15c-4-1-7-1-10 2',scope:'M4 5h16 M4 12h16 M4 19h16',tasks:'M4 6l2 2 3-4 M12 6h8 M4 13l2 2 3-4 M12 13h8 M4 20h5 M12 20h8'})[k]}"/></svg>${pages[k]}</a>`).join('')}`).join('')}</nav><div class="sidebar-foot">本机服务<small>真实工程 · 按功能展示支持范围</small><a href="/index.html#/clinic/home">交互演示 ↗</a></div></aside><div class="main"><header class="project-bar"><h1>${esc(project.name)}</h1><span>${project.hasFramework?'已发现框架':'未发现框架'}</span><span class="updated">读取于 ${new Date(project.checkedAt).toLocaleTimeString()}</span></header><main>${content()}</main></div></div>`}
async function request(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{'X-Workbench-Request':'1',...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const x=await r.json();if(!r.ok)throw Error(x.error||'请求失败');return x}
function modal(h,body){const d=document.getElementById('drawer');d.innerHTML=`<div class="dialog-head"><h2>${h}</h2>${button('关闭','close')}</div>${body}`;if(!d.open)d.showModal()}
const labels={'web.basePath':'Web 根路径','web.cspBasePath':'CSP 根路径','web.brokerPath':'Broker 相对路径','web.cookie':'Web Cookie','sftp.host':'SFTP 主机','sftp.port':'SFTP 端口','sftp.username':'SFTP 账号','sftp.password':'SFTP 密码','sftp.localPath':'本地前端目录','sftp.remotePath':'远端 Web 目录',host:'IRIS 主机',port:'Web 端口',scheme:'协议',namespace:'命名空间',alias:'VS Code 服务器名',description:'连接说明',tlsVerify:'验证 TLS 证书',username:'账号',password:'密码',connection:'服务连接地址',access_key:'统一访问 Key','X-Gateway-Upstream-BOS-MCP-TOKEN':'查询个人 Token',cuser:'人员标识',cgroup:'组标识',token:'日志个人 Token',linkProject:'关联工程',timeout:'请求超时',defaultProvider:'默认提供方',type:'提供方类型',model:'模型',dimensions:'向量维度',baseUrl:'服务地址',method:'请求方法',appId:'应用标识',appKey:'应用 Key',apiKey:'API Key'};
const settingsSection=(field,id)=>id==='bos'?field.id.split('.')[0]:field.id.split('.').slice(0,-1).join('.');
function settingsGroup(field,id){
 const section=settingsSection(field,id);
 if(id==='project'){
  const name=section==='web'?'Web 路径与会话':section==='sftp'?'SFTP 文件连接':'IRIS 开发连接';
  const source=section==='web'?'.agents/config/project-env.json · web':section==='sftp'?'.agents/config/project-env.json · sftp；同步现有 MCP 连接':'集中 IRIS 配置、VS Code 与 MCP/TOML；保存时同步';
  return `<h3 class="fields-group">${name}<small>当前工程 · ${source}</small></h3>`;
 }
 const names={'bos-demand-query':'BOS 需求查询','bos-code-update-log':'BOS 开发日志','providers.company':'公司知识提供方','providers.openai':'OpenAI 知识提供方'};
 const source=id==='bos'?'BOS_MCP_CONFIG':'KNOWLEDGE_RAG_CONFIG';
 return `<h3 class="fields-group">${esc(names[section]||'默认提供方')}<small>共享个人配置 · ${source}${section?' / '+esc(section):' / defaultProvider'}</small></h3>`;
}
async function edit(id){modal('读取个人配置','<p>正在读取已绑定来源…</p>');try{model=await request('/settings/'+id);planId=null;modal(id==='project'?'工程连接与路径':id==='bos'?'BOS 连接与凭据':'知识提供方与 Key',`<div class="notice warning">${id==='project'?'仅当前工程；预览列出涉及文件，保存后逐文件校验。不发起远端请求。':'共享个人配置：保存影响所有引用同一来源的工程，不发起远端请求。'}</div><p class="caption">${id==='project'?'凭据不回显；IRIS 账号与密码需成对替换，其余字段可单独修改。':'地址可能含访问参数，因此也不回显。无需修改时保留。'}</p><form id="settings-form" autocomplete="off"><div class="settings-fields">${model.fields.map((f,i)=>`${i===0||settingsSection(f,id)!==settingsSection(model.fields[i-1],id)?settingsGroup(f,id):''}<div class="field"><label for="${f.secret?'action':'value'}-${i}">${esc(labels[f.label]||f.label)}</label>${f.secret?`<select id="action-${i}" data-secret="${i}"><option value="keep">保留 · ${f.configured?'已设置':'未设置'}</option><option value="replace">替换</option>${id==='project'?'':'<option value="clear">清除</option>'}</select><input id="value-${i}" type="password" hidden disabled autocomplete="new-password" aria-label="${esc(labels[f.label]||f.label)}新值" placeholder="输入替换值">`:`${f.type==='boolean'?`<select id="value-${i}"><option value="true" ${f.value?'selected':''}>是</option><option value="false" ${!f.value?'selected':''}>否</option></select>`:`<input id="value-${i}" value="${esc(f.value)}" type="${f.type==='number'?'number':'text'}">`}`}</div>`).join('')}</div><p id="settings-error" class="error-text" role="alert"></p><div class="form-footer"><span>${id==='project'?'同步工程配置；保存前核对涉及文件':'预览确认后才写入原个人文件'}</span><button class="primary" type="submit">预览修改</button></div></form>`)}catch(e){modal('配置暂不可编辑',`<div class="notice error">${esc(e.message)}</div><p>原配置未修改，请核对来源绑定或格式。</p>`)}}
document.addEventListener('change',e=>{if(e.target.dataset.secret!==undefined){const input=document.getElementById('value-'+e.target.dataset.secret);input.hidden=e.target.value!=='replace';input.disabled=input.hidden;if(input.hidden)input.value=''}});
document.addEventListener('submit',async e=>{if(e.target.id!=='settings-form')return;e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');submit.disabled=true;const changes={};model.fields.forEach((f,i)=>{const value=document.getElementById('value-'+i).value;if(f.secret){const action=document.getElementById('action-'+i).value;if(action!=='keep')changes[f.id]={action,value}}else{const typed=f.type==='number'?Number(value):f.type==='boolean'?value==='true':value;if(typed!==f.value)changes[f.id]={value:typed}}});try{const p=await request('/settings/plan/'+model.id,{revision:model.revision,changes});planId=p.planId;form.querySelectorAll('input[type=password]').forEach(x=>x.value='');modal(model.id==='project'?'确认工程配置修改':'确认共享配置修改',`<div class="notice warning">${esc(p.scope)}</div><p>${esc(p.warning)}</p>${p.changes.length?table([model.id==='project'?'涉及文件':'字段','修改'],p.changes.map(c=>`<tr><td>${esc(c.field)}</td><td>${esc({replace:'替换',clear:'清除'}[c.action]||c.action)}</td></tr>`)):empty('没有实际变更','原配置保持不变。')}<p class="caption">预览 5 分钟有效；保存前检查来源，保存后读回。保留未知字段、BOM 与换行。</p><div class="form-footer">${button('重新编辑','edit-'+model.id)}${p.changes.length?button(model.id==='project'?'保存到当前工程':'保存到共享个人配置','apply',true):''}</div>`)}catch(e){document.getElementById('settings-error').textContent=e.message;submit.disabled=false}});
document.addEventListener('click',async e=>{const d=e.target.closest('[data-doc]');if(d){const m=manuals.find(x=>x.file===d.dataset.doc);if(!m)return;docTitle=m.title;doc='正在读取…';page='manual';location.hash='manual';render();try{const r=await fetch('/manual/'+encodeURIComponent(m.file));if(!r.ok)throw Error();doc=await r.text()}catch{doc='读取失败，请重新选择。'}render();return}const b=e.target.closest('[data-do]');if(!b)return;const a=b.dataset.do;if(a==='close'){document.getElementById('drawer').close();model=null;planId=null;document.getElementById('drawer').innerHTML='';return}if(a==='refresh'){await load();return}if(a.startsWith('plugin-')){const p=catalog.plugins.find(x=>x.name===a.slice(7));const deps=new Set();const visit=n=>{if(deps.has(n))return;deps.add(n);const found=catalog.plugins.find(x=>x.name===n);found?.dependencies.forEach(visit)};visit(p.name);modal('插件管理预览',`<p>目标：${esc(pluginNames[p.name]||p.name)}</p><p class="caption">按源仓依赖计算；这是本地计划，不执行安装或启停。</p>${table(['能力','当前工程状态','计划影响'],[...deps].map(n=>`<tr><td>${esc(pluginNames[n]||n)}</td><td>${esc(status(project.plugins.find(x=>x.name===n)?.status))}</td><td>${n===p.name?'核对目标启用与配置':'保留或补齐依赖'}</td></tr>`))}<div class="notice">真实执行依赖 plugin-management 的 sparse checkout、初始化和 profile 更新；当前 HTTP 服务尚未接入进程生命周期与取消恢复，不能直接执行安装。</div>${button('生成安装或启用请求','handoff-'+p.name,true)}`);return}if(a.startsWith('edit-')){await edit(a.slice(5));return}if(a==='apply'){b.disabled=true;try{const r=await request('/settings/apply',{planId});activity.unshift(model.id==='project'?'工程配置已保存并读回':'个人配置已保存并读回');modal('保存结果',`<div class="notice success">${esc(r.message)}</div><p>必要时重新加载客户端；远端认证未验证。</p>`);await load()}catch(e){modal('保存未完成',`<div class="notice error">${esc(e.message)}</div>${button('重新读取','edit-'+model.id)}`)}return}if(a.startsWith('handoff-')){modal('接续到 Agent',`<p>复制后在当前工程客户端执行。复制不代表完成。</p><textarea id="handoff" readonly>工程：${esc(project.name)}\n目标：${esc(a.slice(8))}\n先读取当前工程 AGENTS.md 与对应 owner 入口，核对来源与影响。保留已有配置、不回显凭据、不提交或推送。共享配置、远端写入及外发内容需用户确认。完成后读回实际结果并列出未验证事项。\n工作台仅完成识别，尚未执行该任务。</textarea>${button('复制请求','copy',true)}`);return}if(a==='copy'){try{await navigator.clipboard.writeText(document.getElementById('handoff').value);b.textContent='已复制 · 等待执行'}catch{b.textContent='请选中文本手动复制'}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(pos,pos)}});
addEventListener('hashchange',()=>{page=pages[location.hash.slice(1)]?location.hash.slice(1):'home';search='';if(project)render()});
async function load(){try{const results=await Promise.all([fetch('/project.json').then(r=>r.json()),fetch('/catalog.json').then(r=>r.json()),fetch('/manuals.json').then(r=>r.json())]);if(results[0].error)throw Error(results[0].error);[project,catalog,manuals]=results;if(!doc){const first=manuals.find(x=>x.file==='usage-manual.md')||manuals[0];if(first){docTitle=first.title;doc=await fetch('/manual/'+encodeURIComponent(first.file)).then(r=>r.text())}}page=pages[location.hash.slice(1)]?location.hash.slice(1):'home';render()}catch(e){document.getElementById('actual').innerHTML=empty('无法读取绑定工程',esc(e.message),button('重试','refresh'))}}load();
